require_once __DIR__.'/fixtures/PortalAccessFixture.php';
require_once __DIR__.'/fixtures/ServerOwnerApprovalFixture.php';
final class GlobalPrimaryOwnerTest extends WP_UnitTestCase {
 protected function setUp():void{parent::setUp();PortalAccessFixture::reset();ServerOwnerApprovalFixture::clear();}
 protected function tearDown():void{global $wpdb;$_GET=[];ServerOwnerApprovalFixture::clear();$wpdb->query('COMMIT');PortalAccessFixture::reset();$wpdb->query('COMMIT');$wpdb->query('START TRANSACTION');parent::tearDown();}
 private function identity():void{$existing=get_user_by('email',Owner::EMAIL);if($existing&&$existing->ID!==1)wp_update_user(['ID'=>$existing->ID,'user_email'=>'prior-global-fixture@example.invalid']);wp_update_user(['ID'=>1,'user_email'=>Owner::EMAIL]);$u=get_userdata(1);$u->set_role('administrator');foreach(DigiForge\Core\Capabilities::ALL as $c)$u->add_cap($c);}
 private function sign():void{self::assertTrue(class_exists(GlobalOwnerAuthority::class));ServerOwnerApprovalFixture::write();}
 private function email():void{$this->identity();wp_set_current_user(0);$_COOKIE=[];$code='';$mail=static function($pre,$p)use(&$code){preg_match('/\b([0-9]{8})\b/',$p['message'],$m);$code=$m[1]??'';return true;};add_filter('pre_wp_mail',$mail,PHP_INT_MAX,2);try{$r=Authentication::process(['email'=>Owner::EMAIL,'return_to'=>add_query_arg(['df_view'=>'owner'],home_url('/')),'challenge'=>Authentication::browserChallenge(),'_wpnonce'=>wp_create_nonce(Authentication::ACTION)]);self::assertNotWPError($r);self::assertNotEmpty($code);self::assertNotWPError(Authentication::process(['step'=>'verify','selector'=>$r['selector'],'code'=>$code,'challenge'=>Authentication::browserChallenge(),'_wpnonce'=>wp_create_nonce(Authentication::ACTION)]));}finally{remove_filter('pre_wp_mail',$mail,PHP_INT_MAX);}}
 private function enroll():array{$this->sign();$this->email();$r=OwnerBootstrap::enroll('',wp_generate_uuid4());self::assertNotWPError($r,is_wp_error($r)?'initial enrollment: '.$r->get_error_code():'');return $r;}
 public function testExplicitGlobalOwnerGetsFourNativeAssignmentsAndGlobalConsole():void{$s=$this->enroll();self::assertSame('Global Primary Owner',$s['role']);self::assertSame(ShopAccessPolicy::canonicalShops(),array_keys($s['shops']));self::assertTrue(Session::valid($s));foreach(ShopAccessPolicy::canonicalShops() as $shop){self::assertTrue(Owner::require($shop));foreach(['manage_digiforge','manage_digiforge_products','manage_digiforge_research','manage_digiforge_connections','manage_digiforge_settings','manage_digiforge_orders','manage_digiforge_listings'] as $cap)self::assertTrue(ShopAccess::authorize($shop,$cap));}self::assertSame(ShopAccessPolicy::canonicalShops(),ShopAccess::allowedShops('manage_digiforge'));$_GET=['df_view'=>'dashboard','df_shop'=>'all'];$html=(new DigiForge\Portal\Portal())->render();self::assertStringContainsString('Operations Console',$html);self::assertStringNotContainsString('An explicit assignment is required',$html);}
 public function testGlobalOwnerCanEnterReviewedModuleEndpointsWithoutBypassingContracts():void{$this->enroll();foreach([['GET','/digiforge/v1/products'],['GET','/digiforge/v1/integrations'],['POST','/digiforge/v1/research/sources'],['POST','/digiforge/v1/orders'],['GET','/digiforge/v1/controls']] as [$method,$path])self::assertNull((new Guard())->rest(null,[],new WP_REST_Request($method,$path)),$path);self::assertWPError((new Guard())->rest(null,[],new WP_REST_Request('GET','/digiforge/v1/future-sensitive')));self::assertStringContainsString('user management',DigiForge\PortalAccess\Panel::render());$panel=DigiForge\PortalAccess\Panel::render();foreach(ShopAccessPolicy::canonicalShops() as $shop)self::assertStringContainsString('df_shop='.$shop,$panel);}
 public function testLegacyShopTwoAuthorityCannotEnrollGlobalOwner():void{$this->identity();PortalAccessFixture::sign(1);$this->email();self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));self::assertNull(Store::read(1));self::assertSame('DATABASE_AUTHORITY_OR_APPROVAL_INVALID',OwnerReadiness::inspect('personalized_pod')['state']);}
 public function testEmailAndAdministratorStatusCannotReplaceServerApproval():void{$this->identity();$this->email();self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));$this->sign();get_userdata(1)->add_cap('manage_digiforge_orders',false);self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));self::assertNull(Store::read(1));}
 public function testConflictingDuplicatePartialAndWrongSiteAuthoritiesAreRejected():void{$this->identity();$this->sign();$records=GlobalOwnerAuthority::draft(home_url('/'),time()+3600,hash('sha256','synthetic-records'));foreach([array_slice($records,0,3),array_merge($records,[$records[0]]),array_replace($records,[0=>array_replace($records[0],['actor_id'=>2])]),array_map(static fn($r)=>array_replace($r,['site'=>'https://foreign.invalid/']),$records)] as $bad){ServerOwnerApprovalFixture::storeRecords($bad);self::assertWPError(GlobalOwnerAuthority::current());}self::assertNull(Store::read(1));}
 public function testAuthorityRevocationExpiresGlobalSessionAndEveryShop():void{$s=$this->enroll();ServerOwnerApprovalFixture::clear();delete_option('digiforge_portal_database_owner_authority');self::assertFalse(Session::valid($s));foreach(ShopAccessPolicy::canonicalShops() as $shop)self::assertWPError(ShopAccess::authorize($shop,'manage_digiforge'));self::assertWPError((new Guard())->rest(null,[],new WP_REST_Request('GET','/digiforge/v1/products')));self::assertTrue(is_user_logged_in());}
 public function testNativeGrantRevocationInvalidatesGlobalSession():void{$s=$this->enroll();$repo=new ShopAccessRepository();$native=$repo->read('jewelry');self::assertNotWPError($repo->revoke('jewelry',$s['global_grants']['jewelry'],wp_generate_uuid4(),$native['revision']));self::assertFalse(Session::valid($s));self::assertWPError(Owner::require('digital'));}
 public function testDelegatedViewerRemainsScopedAndCannotBecomeGlobalOwner():void{$this->enroll();$id=self::factory()->user->create(['role'=>'administrator']);self::assertNotWPError(Store::change($id,'Viewer',['personalized_pod'=>['overview','research','personalized_pod','integrations']],true,0,wp_generate_uuid4()));PortalAccessFixture::login($id);self::assertTrue(Session::start());self::assertTrue(ShopAccess::authorize('personalized_pod','manage_digiforge_research'));self::assertWPError(ShopAccess::authorize('digital','manage_digiforge_research'));self::assertWPError(Owner::require('personalized_pod'));self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));self::assertWPError((new Guard())->rest(null,[],new WP_REST_Request('POST','/digiforge/v1/research/sources')));}
 public function testDuplicateAndCompetingClaimsNeverCreateAnotherOwner():void{$this->sign();$this->email();global $wpdb;$other=null;$race=null;$race=static function($sql)use(&$race,&$other){if(str_starts_with($sql,'INSERT')&&str_contains($sql,OwnerBootstrap::KEY)){remove_filter('query',$race);$other=OwnerBootstrap::enroll('',wp_generate_uuid4());}return $sql;};add_filter('query',$race);$prior=$wpdb->suppress_errors(true);try{$r=OwnerBootstrap::enroll('',wp_generate_uuid4());}finally{remove_filter('query',$race);$wpdb->suppress_errors($prior);}self::assertSame(1,(int)is_wp_error($r)+(int)is_wp_error($other));self::assertSame('Global Primary Owner',Store::read(1)['role']);foreach(ShopAccessPolicy::canonicalShops() as $shop)self::assertSame(1,(new ShopAccessRepository())->read($shop)['revision']);self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));}
 public function testInterruptedFourShopEnrollmentIsDisabledAndLegacyHandlerCannotResume():void{$this->sign();$this->email();global $wpdb;$prior=$wpdb->suppress_errors(true);$deny=static function($sql){return str_starts_with($sql,'INSERT')&&str_contains($sql,'digiforge_shop_access_event_')&&str_contains($sql,'standard_pod')?'UPDATE missing_global_enrollment_fixture SET value=1':$sql;};add_filter('query',$deny);try{$r=OwnerBootstrap::enroll('',wp_generate_uuid4());}finally{remove_filter('query',$deny);$wpdb->suppress_errors($prior);}self::assertWPError($r);$s=Store::read(1);self::assertIsArray($s);self::assertFalse($s['enabled']);self::assertTrue($s['bootstrap_pending']);self::assertFalse(Session::valid($s));self::assertWPError(ShopAccess::authorize('digital','manage_digiforge'));self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));self::assertSame('GLOBAL_ENROLLMENT_INTERRUPTED',OwnerReadiness::inspect('digital')['state']);self::assertWPError((new Feature())->process('digiforge_portal_owner_enroll',['_wpnonce'=>wp_create_nonce('digiforge_portal_owner_enroll'),'confirm'=>'CONFIRM_DIGIFORGE_ONLY','shop'=>'digital','request_id'=>wp_generate_uuid4()]));}
 public function testOwnershipDoesNotEnableExternalExecutionOrInactiveShops():void{$table=DigiForge\Database\Tables::settings();global $wpdb;$before=$wpdb->get_results("SELECT setting_key,setting_value,setting_type FROM {$table} ORDER BY setting_key",ARRAY_A);$this->enroll();self::assertSame($before,$wpdb->get_results("SELECT setting_key,setting_value,setting_type FROM {$table} ORDER BY setting_key",ARRAY_A));self::assertTrue(DigiForge\Core\Settings::safety_locked());foreach(['printify','etsy_publish','order_automation','gst_automation'] as $switch)self::assertFalse(DigiForge\Core\Settings::is_enabled($switch));self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertFalse(DigiForge\Core\Settings::get('automation_enabled',false));$calls=0;$r=(new DigiForge\POD\PrintifyControlledTransport(static function()use(&$calls){$calls++;return [];}))->executeProduct(str_repeat('a',64),str_repeat('b',64));self::assertWPError($r);self::assertSame(0,$calls);}
 public function testInterruptedClaimAndAuditRollbackTogetherBeforeAnyNativeGrant():void{$this->sign();$this->email();global $wpdb;$throw=static function($sql){if(str_starts_with($sql,'INSERT')&&str_contains($sql,'portal_global_owner_claimed'))throw new RuntimeException('synthetic claim interruption');return $sql;};add_filter('query',$throw);try{$r=OwnerBootstrap::enroll('',wp_generate_uuid4());}finally{remove_filter('query',$throw);}self::assertWPError($r);self::assertNull(Store::read(1));self::assertNull($wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",OwnerBootstrap::KEY)));foreach(ShopAccessPolicy::canonicalShops() as $shop)self::assertSame(0,(new ShopAccessRepository())->read($shop)['revision']);}

 public function testInvalidExpiredAndWrongActorApprovalsAreNeverGlobal():void{$this->identity();foreach([['actor_id'=>2],['email'=>'other@example.invalid'],['site'=>'https://foreign.invalid/'],['scope'=>'OWNER'],['purpose'=>'RECOVER'],['expires_at'=>time()-1],['expires_at'=>time()+86410],['authority_expires_at'=>time()-1],['authority_expires_at'=>time()+367*86400],['approval_id'=>'bad'],['version'=>2]] as $bad){ServerOwnerApprovalFixture::write($bad);self::assertWPError(GlobalOwnerAuthority::current(),wp_json_encode($bad));}ServerOwnerApprovalFixture::write();chmod(ServerOwnerApprovalFixture::path(),0644);self::assertWPError(GlobalOwnerAuthority::current());$this->sign();PortalAccessFixture::login(self::factory()->user->create(['role'=>'administrator']));self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));self::assertNull(Store::read(1));}
 public function testLegacySignedGlobalEnvelopeCannotReplaceServerApproval():void{$this->identity();SyntheticShopAuthority::write(GlobalOwnerAuthority::draft(home_url('/'),time()+3600,hash('sha256','old-global')));$this->email();self::assertWPError(GlobalOwnerAuthority::current());self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));self::assertNull(Store::read(1));}
 public function testDatabaseAuthorityTamperingRevokesEveryShop():void{$s=$this->enroll();global $wpdb;$raw=$wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",'digiforge_portal_database_owner_authority'));$stored=json_decode($raw,true);$stored['body']['records'][0]['expires_at']++;$wpdb->update($wpdb->options,['option_value'=>wp_json_encode($stored)],['option_name'=>'digiforge_portal_database_owner_authority']);self::assertWPError(GlobalOwnerAuthority::current());self::assertFalse(Session::valid($s));foreach(ShopAccessPolicy::canonicalShops() as $shop)self::assertWPError(ShopAccess::authorize($shop,'manage_digiforge'));}
 public function testPersistedAuthoritySurvivesHostApprovalRemoval():void{$s=$this->enroll();ServerOwnerApprovalFixture::clear();SyntheticShopAuthority::clear();self::assertNotWPError(GlobalOwnerAuthority::current());self::assertTrue(Session::valid($s));}
 public function testLegacyOwnerProfileIsUpgradedInPlaceOnlyUnderExplicitGlobalAuthority():void{$this->identity();PortalAccessFixture::sign(1);PortalAccessFixture::login(1);self::assertNotWPError(Store::save(['actor_id'=>1,'role'=>'Primary Owner','enabled'=>true,'revision'=>1,'generation'=>1,'shops'=>['personalized_pod'=>DigiForge\Core\Capabilities::ALL]],0,wp_generate_uuid4()));$old=Store::read(1);$this->sign();$this->email();$r=OwnerBootstrap::enroll('',wp_generate_uuid4());self::assertNotWPError($r);self::assertSame(GlobalOwnerAuthority::ROLE,$r['role']);self::assertSame($old['revision']+2,$r['revision']);self::assertSame($old['generation']+2,$r['generation']);self::assertCount(4,$r['shops']);self::assertSame(1,$r['actor_id']);}
 public function testPendingOwnerCanReverifyEmailAndRequiresExactReviewedRecovery():void{$this->sign();$this->email();global $wpdb;$deny=static function($sql){return str_starts_with($sql,'INSERT')&&str_contains($sql,'digiforge_shop_access_event_')&&str_contains($sql,'jewelry')?'UPDATE missing_recovery_fixture SET value=1':$sql;};add_filter('query',$deny);$prior=$wpdb->suppress_errors(true);try{self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));}finally{remove_filter('query',$deny);$wpdb->suppress_errors($prior);}$this->email();self::assertTrue(EmailAuthentication::recent(1));self::assertFalse(Session::valid(Store::read(1)));$plan=OwnerBootstrap::recoveryPlan();self::assertNotWPError($plan);self::assertWPError(OwnerBootstrap::recover('',wp_generate_uuid4()));ServerOwnerApprovalFixture::write(['purpose'=>'RECOVER','recovery_scope_sha256'=>$plan['scope_sha256']]);$r=OwnerBootstrap::recover('',wp_generate_uuid4());self::assertNotWPError($r);self::assertTrue(Session::valid($r));self::assertTrue(Owner::require('jewelry'));self::assertWPError(OwnerBootstrap::recover('',wp_generate_uuid4()));
  add_filter('query',$deny);$prior=$wpdb->suppress_errors(true);try{self::assertWPError(OwnerBootstrap::renew(wp_generate_uuid4()));}finally{remove_filter('query',$deny);$wpdb->suppress_errors($prior);}$newPlan=OwnerBootstrap::recoveryPlan();self::assertNotWPError($newPlan);self::assertNotSame($plan['scope_sha256'],$newPlan['scope_sha256']);$wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->options} WHERE option_name LIKE %s",$wpdb->esc_like('digiforge_portal_rate_').'%'));$stale=OwnerBootstrap::recover('',wp_generate_uuid4());self::assertWPError($stale);self::assertSame('digiforge_portal_global_recovery_approval',$stale->get_error_code());}
 public function testExplicitRenewalRotatesGenerationButCannotUndoRevocation():void{$s=$this->enroll();$oldCookie=$_COOKIE[Session::name()];$r=OwnerBootstrap::renew(wp_generate_uuid4());self::assertNotWPError($r);self::assertSame($s['generation']+2,$r['generation']);$newCookie=$_COOKIE[Session::name()];$_COOKIE[Session::name()]=$oldCookie;self::assertFalse(Session::valid($r));$_COOKIE[Session::name()]=$newCookie;self::assertTrue(Session::valid($r));$repo=new ShopAccessRepository();$n=$repo->read('digital');self::assertNotWPError($repo->revoke('digital',$r['global_grants']['digital'],wp_generate_uuid4(),$n['revision']));self::assertFalse(Session::valid($r));self::assertWPError(OwnerBootstrap::renew(wp_generate_uuid4()));}

 public function testExpiredNativeAssignmentsCanRenewOnlyWithCurrentUnrevokedGlobalAuthority():void{$profile=$this->enroll();global $wpdb;$repo=new ShopAccessRepository();$state=$repo->read('digital');$id=$profile['global_grants']['digital'];$state['grants'][$id]['expires_at']=time()-1;$key='digiforge_shop_access_event_'.$id;$event=json_decode($wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",$key)),true);$event['grant']=$state['grants'][$id];$event['created_at']=time()-3601;$raw=wp_json_encode($event);$wpdb->update($wpdb->options,['option_value'=>$raw],['option_name'=>$key]);$wpdb->update($wpdb->options,['option_value'=>wp_json_encode($state)],['option_name'=>'digiforge_shop_access_state_digital']);$wpdb->update(DigiForge\Database\Tables::audit_log(),['context'=>$raw],['object_type'=>'shop_access','event_type'=>'shop_access_grant','object_id'=>$id],['%s'],['%s','%s','%s']);$read=$repo->read('digital');self::assertNotWPError($read,is_wp_error($read)?'expired fixture: '.$read->get_error_code():'');self::assertFalse(Session::valid($profile));$this->email();self::assertFalse(Session::valid(Store::read(1)));$r=OwnerBootstrap::renew(wp_generate_uuid4());self::assertNotWPError($r,is_wp_error($r)?$r->get_error_code():'');self::assertTrue(Session::valid($r));self::assertTrue(Owner::require('digital'));}

 public function testLegacyNativeOwnerEnrollmentAndDelegationCannotBypassGlobalBootstrap():void{$this->sign();$this->identity();PortalAccessFixture::login(1);$a=GlobalOwnerAuthority::current();$repo=new ShopAccessRepository();$other=self::factory()->user->create(['role'=>'administrator']);self::assertWPError($repo->enrollOwner('digital','administrator',DigiForge\Core\Capabilities::ALL,time()+600,$a['source_approval_hash'],wp_generate_uuid4(),0));self::assertWPError($repo->grant($other,'digital','administrator',['manage_digiforge'],time()+600,wp_generate_uuid4(),0));self::assertNull(Store::read(1));}

 public function testRenewalCannotReauthorizeAConcurrentRevocation():void{$s=$this->enroll();global $wpdb;$race=null;$revoked=null;$race=static function($sql)use(&$race,&$revoked,$s){if(str_starts_with($sql,'SELECT option_name')&&str_contains(str_replace(chr(92),'',$sql),'digiforge_portal_profile_')){remove_filter('query',$race);$repo=new ShopAccessRepository();$n=$repo->read('digital');$revoked=$repo->revoke('digital',$s['global_grants']['digital'],wp_generate_uuid4(),$n['revision']);}return $sql;};add_filter('query',$race);try{$r=OwnerBootstrap::renew(wp_generate_uuid4());}finally{remove_filter('query',$race);}self::assertIsArray($revoked);self::assertNotWPError($revoked);self::assertWPError($r);self::assertFalse(Session::valid(Store::read(1)));self::assertSame(2,(new ShopAccessRepository())->read('digital')['revision']);self::assertSame(1,(new ShopAccessRepository())->read('jewelry')['revision']);}

 public function testOwnerRevocationRequiresFreshOtpAndCsrfThenInvalidatesEveryShop():void {
  $profile=$this->enroll();$feature=new Feature();$action='digiforge_portal_owner_revoke';$input=['scope'=>'GLOBAL_PRIMARY_OWNER','confirm'=>'CONFIRM_DIGIFORGE_ONLY','request_id'=>wp_generate_uuid4()];
  self::assertWPError($feature->process($action,$input));self::assertTrue(Session::valid($profile));$input['_wpnonce']=wp_create_nonce($action);
  $r=$feature->process($action,$input);self::assertNotWPError($r);self::assertFalse($r['enabled']);self::assertFalse(Session::valid($r));foreach(ShopAccessPolicy::canonicalShops() as $shop)self::assertWPError(ShopAccess::authorize($shop,'manage_digiforge'));
  self::assertWPError(OwnerBootstrap::enroll('',wp_generate_uuid4()));self::assertWPError(OwnerBootstrap::renew(wp_generate_uuid4()));self::assertSame('GLOBAL_ACCESS_REVOKED_OR_EXPIRED',OwnerReadiness::inspect('digital')['state']);self::assertNotWPError(OwnerBootstrap::recoveryPlan());
 }
